<?php require __DIR__.'/../includes/functions.php'; admin_required(); $edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM reviews WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();} if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM reviews WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:reviews.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$old=$id?$pdo->query('SELECT image FROM reviews WHERE id='.$id)->fetchColumn():null;$image=upload_image('image',$old);if($id)$pdo->prepare('UPDATE reviews SET name=?,location=?,review=?,rating=?,image=?,sort_order=? WHERE id=?')->execute([$_POST['name'],$_POST['location'],$_POST['review'],(int)$_POST['rating'],$image,(int)$_POST['sort_order'],$id]);else $pdo->prepare('INSERT INTO reviews(name,location,review,rating,image,sort_order) VALUES(?,?,?,?,?,?)')->execute([$_POST['name'],$_POST['location'],$_POST['review'],(int)$_POST['rating'],$image,(int)$_POST['sort_order']]);header('Location:reviews.php');exit;} $items=$pdo->query('SELECT * FROM reviews ORDER BY sort_order,id')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><title>Reviews</title><link rel="stylesheet" href="admin.css"></head><body><div class="top"><div class="wrap"><b>Reviews</b><a href="index.php" style="color:#fff">← Admin</a></div></div><div class="wrap" style="padding:30px 0"><div class="card"><h2><?= $edit?'Edit':'Add' ?> review</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><input name="name" placeholder="Name" value="<?=e($edit['name']??'')?>" required><input name="location" placeholder="Country / city" value="<?=e($edit['location']??'')?>"><textarea name="review" placeholder="Review" rows="4" required><?=e($edit['review']??'')?></textarea><input name="rating" type="number" min="1" max="5" value="<?=e($edit['rating']??5)?>"><input name="sort_order" type="number" value="<?=e($edit['sort_order']??1)?>"><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="button">Save</button></form></div><div class="grid"><?php foreach($items as $x):?><div class="card"><?php if($x['image']):?><img class="thumb" src="../<?=e($x['image'])?>"><?php endif;?><h3><?=e($x['name'])?></h3><p><?=e($x['review'])?></p><a class="button" href="?edit=<?=$x['id']?>">Edit</a> <a class="button danger" onclick="return confirm('Delete?')" href="?delete=<?=$x['id']?>">Delete</a></div><?php endforeach;?></div></div></body></html>
